pub(super) fn parse_source(source: &[u8]) -> Result<Manifest> {
    model::parse(source)
}

pub(super) fn load_verified_manifest(store: &ObjectStore, cid: &str) -> Result<Manifest> {
    model::load_verified(store, cid)
}

pub(super) fn construct(
    store: &ObjectStore,
    source: Vec<u8>,
    manifest: Manifest,
    executable: Vec<u8>,
    runtime_files: Vec<super::runtime_support::FileInput>,
    environment: &[String],
    mut metadata_refs: Vec<(String, String)>,
) -> Result<Built> {
    let environment = provision::inputs::parse_environment(environment)?;
    let source_cid = value::put_value(
        store,
        &value::artifact_value("native_package_manifest_source", source),
    )?;
    let manifest_cid = model::store(store, &manifest, &source_cid)?;
    metadata_refs.push(("native_package_manifest".to_owned(), manifest_cid.clone()));
    metadata_refs.sort_by(|left, right| left.0.cmp(&right.0));
    let capsule = value::store(
        store,
        value::CapsuleInputs {
            name: &manifest.name,
            executable,
            os_support_executable: None,
            script: None,
            package_manifest: None,
            package_lock: None,
            package_files: Vec::new(),
            runtime_support_files: runtime_files,
            native_library_paths: manifest.native_libraries.clone(),
            python_wheel_archives: Vec::new(),
            script_extension: "",
            arguments: &manifest.arguments,
            environment: &environment,
            module_metadata_refs: &metadata_refs,
        },
    )?;
    let materialized = provision::materialize_inner(store, &capsule.module_cid)?;
    if materialized.capsule_cid != capsule.capsule_cid {
        bail!("native package capsule did not replay after construction");
    }
    Ok(Built {
        manifest,
        manifest_cid,
        source_cid,
        capsule,
    })
}

